//! Versioned lore save migration shell.
#![allow(dead_code)]
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum LoreSaveVersion{V0,V1,V2}
#[derive(Debug,Clone,Copy,Default)] pub struct WorldLoreStateV1{pub world_seed:u64,pub event_ledger_hash:u64,pub public_memory_hash:u64,pub first_lock_mask:u16,pub echo_lock_mask:u16,pub puzzle_scar_count:u32,pub death_scar_count:u32,pub vowless_blank_count:u32}
#[derive(Debug,Clone,Copy,Default)] pub struct WorldLoreStateV2{pub world_seed:u64,pub event_ledger_hash:u64,pub public_memory_hash:u64,pub first_lock_mask:u16,pub echo_lock_mask:u16,pub puzzle_scar_count:u32,pub death_scar_count:u32,pub vowless_blank_count:u32,pub harmonic_state_hash:u64,pub disclosure_stage:u8,pub save_schema_hash:u64}
pub fn migrate_v1_to_v2(v1:WorldLoreStateV1)->WorldLoreStateV2{let mut v2=WorldLoreStateV2{world_seed:v1.world_seed,event_ledger_hash:v1.event_ledger_hash,public_memory_hash:v1.public_memory_hash,first_lock_mask:v1.first_lock_mask,echo_lock_mask:v1.echo_lock_mask,puzzle_scar_count:v1.puzzle_scar_count,death_scar_count:v1.death_scar_count,vowless_blank_count:v1.vowless_blank_count,harmonic_state_hash:0,disclosure_stage:0,save_schema_hash:0};v2.save_schema_hash=save_schema_hash_v2(v2);v2}
pub fn save_schema_hash_v2(s:WorldLoreStateV2)->u64{let mut h=0xcbf29ce484222325u64;for v in[s.world_seed,s.event_ledger_hash,s.public_memory_hash,s.first_lock_mask as u64,s.echo_lock_mask as u64,s.puzzle_scar_count as u64,s.death_scar_count as u64,s.vowless_blank_count as u64,s.harmonic_state_hash,s.disclosure_stage as u64]{h^=v;h=h.wrapping_mul(0x100000001b3)}h}
